<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/notifications.php'; requireRole('patient');
if ($_SERVER['REQUEST_METHOD'] === 'POST' && verifyCsrfToken($_POST['csrf_token'] ?? null)) { $notificationId = filter_input(INPUT_POST, 'notification_id', FILTER_VALIDATE_INT); if ($notificationId) { $mark = $pdo->prepare('UPDATE notifications SET is_read = 1 WHERE id = :id AND user_id = :user_id'); $mark->execute([':id' => $notificationId, ':user_id' => $_SESSION['user_id']]); } redirect('notifications.php'); }
$query = $pdo->prepare('SELECT id, title, message, is_read, created_at FROM notifications WHERE user_id = :user_id ORDER BY created_at DESC'); $query->execute([':user_id' => $_SESSION['user_id']]); $notifications = $query->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Notifications'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Patient space</p><h1 class="h2">Notifications</h1></div></div><div class="card border-0 shadow-sm"><div class="card-body"><?php foreach ($notifications as $notification): ?><article class="d-flex justify-content-between gap-3 border-bottom py-3 <?= !$notification['is_read'] ? 'fw-semibold' : '' ?>"><div><h2 class="h6 mb-1"><?= e($notification['title']) ?></h2><p class="mb-1 text-muted"><?= e($notification['message']) ?></p><small class="text-muted"><?= e($notification['created_at']) ?></small></div><?php if (!$notification['is_read']): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="notification_id" value="<?= (int) $notification['id'] ?>"><button class="btn btn-sm btn-outline-primary">Mark read</button></form><?php endif; ?></article><?php endforeach; ?><?php if (!$notifications): ?><p class="text-muted mb-0">No notifications yet.</p><?php endif; ?></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>